4.2 CSS — Estilos clave
/* === RESET &amp; BASE === */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #0a0a0a;
  --bg-light: #141414;
  --text: #e0e0e0;
  --text-muted: #888888;
  --accent-blue: #3b82f6;
  --accent-green: #22c55e;
  --accent-orange: #f59e0b;
  --accent-pink: #ec4899;
  --font-display: &#039;Oswald&#039;, sans-serif;
  --font-body: &#039;Inter&#039;, sans-serif;
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  overflow-x: hidden;
  line-height: 1.6;
}

/* === LOADER === */
#loader {
  position: fixed;
  inset: 0;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  transition: opacity 0.6s var(--ease-out), visibility 0.6s;
}
#loader.hidden {
  opacity: 0;
  visibility: hidden;
}
.loader-logo {
  font-family: var(--font-display);
  font-size: 4rem;
  font-weight: 700;
  color: var(--text);
  animation: pulse 1.5s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

/* === SIDE NAV === */
#side-nav {
  position: fixed;
  right: 2rem;
  top: 50%;
  transform: translateY(-50%);
  z-index: 100;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.nav-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text-muted);
  opacity: 0.4;
  transition: all 0.3s var(--ease-out);
  position: relative;
}
.nav-dot.active {
  background: var(--text);
  opacity: 1;
  transform: scale(1.3);
}
.nav-dot:hover::after {
  content: attr(data-label);
  position: absolute;
  right: 24px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.75rem;
  white-space: nowrap;
  color: var(--text-muted);
}

/* === SLIDES === */
.slide {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6rem 8vw;
  position: relative;
  overflow: hidden;
}

.slide-content {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

/* === HERO === */
#hero {
  text-align: center;
}
.hero-title {
  font-family: var(--font-display);
  font-size: clamp(4rem, 15vw, 12rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.02em;
  margin-bottom: 2rem;
}
.hero-title .line {
  display: block;
}
.hero-title .line.accent {
  font-weight: 200;
  color: var(--text-muted);
}
.hero-subtitle {
  font-size: clamp(1rem, 2.5vw, 1.5rem);
  color: var(--text-muted);
  margin-bottom: 3rem;
  font-weight: 300;
}
.hero-cta {
  display: flex;
  gap: 1.5rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* === BUTTONS === */
.btn-primary {
  display: inline-block;
  padding: 1rem 2.5rem;
  background: var(--text);
  color: var(--bg);
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: none;
  cursor: pointer;
  transition: all 0.3s var(--ease-out);
  text-decoration: none;
}
.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 30px rgba(255,255,255,0.1);
}
.btn-secondary {
  display: inline-block;
  padding: 1rem 2.5rem;
  background: transparent;
  color: var(--text);
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: 1px solid var(--text-muted);
  cursor: pointer;
  transition: all 0.3s var(--ease-out);
  text-decoration: none;
}
.btn-secondary:hover {
  border-color: var(--text);
  transform: translateY(-2px);
}

/* === SCROLL INDICATOR === */
.scroll-indicator {
  position: absolute;
  bottom: 3rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  opacity: 0.6;
}
.mouse {
  width: 24px;
  height: 36px;
  border: 2px solid var(--text-muted);
  border-radius: 12px;
  position: relative;
}
.wheel {
  width: 3px;
  height: 8px;
  background: var(--text-muted);
  border-radius: 2px;
  position: absolute;
  top: 6px;
  left: 50%;
  transform: translateX(-50%);
  animation: scrollWheel 2s ease-in-out infinite;
}
@keyframes scrollWheel {
  0% { opacity: 1; transform: translateX(-50%) translateY(0); }
  100% { opacity: 0; transform: translateX(-50%) translateY(12px); }
}
.scroll-indicator span {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--text-muted);
}

/* === SECTION TITLES === */
.section-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  line-height: 1;
  margin-bottom: 1.5rem;
}
.section-title .accent-blue { color: var(--accent-blue); }
.section-title .accent-green { color: var(--accent-green); }
.section-title .accent-orange { color: var(--accent-orange); }
.section-title .accent-pink { color: var(--accent-pink); }
.section-desc {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 500px;
  margin-bottom: 3rem;
}

/* === LAYOUT SPLIT === */
.layout-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.layout-split.alt {
  direction: rtl;
}
.layout-split.alt &gt; * {
  direction: ltr;
}

/* === CARDS === */
.col-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}
.card {
  background: var(--bg-light);
  padding: 2rem;
  border: 1px solid rgba(255,255,255,0.05);
  transition: all 0.4s var(--ease-out);
  position: relative;
  overflow: hidden;
}
.card::before {
  content: &#039;&#039;;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--card-accent, var(--accent-blue));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s var(--ease-out);
}
.card:hover {
  transform: translateY(-4px);
  border-color: rgba(255,255,255,0.1);
}
.card:hover::before {
  transform: scaleX(1);
}
.card[data-color=&quot;blue&quot;] { --card-accent: var(--accent-blue); }
.card[data-color=&quot;green&quot;] { --card-accent: var(--accent-green); }
.card[data-color=&quot;orange&quot;] { --card-accent: var(--accent-orange); }
.card[data-color=&quot;pink&quot;] { --card-accent: var(--accent-pink); }
.card-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}
.card h3 {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}
.card p {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* === PROJECT LIST === */
.project-item {
  padding: 1.5rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  cursor: pointer;
  transition: all 0.3s var(--ease-out);
  opacity: 0.5;
}
.project-item.active {
  opacity: 1;
  padding-left: 1rem;
  border-left: 2px solid var(--accent-green);
}
.project-item h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 600;
  margin-bottom: 0.3rem;
}
.project-item p {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}
.tag {
  display: inline-block;
  padding: 0.2rem 0.6rem;
  background: rgba(255,255,255,0.05);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-right: 0.5rem;
  color: var(--text-muted);
}

/* === STATS === */
.stats {
  display: flex;
  gap: 3rem;
  margin-top: 2rem;
}
.stat {
  text-align: center;
}
.stat-num {
  display: block;
  font-family: var(--font-display);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--accent-orange);
}
.stat-label {
  font-size: 0.8rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* === PROFILE === */
.profile-frame {
  position: relative;
  aspect-ratio: 3/4;
  max-width: 350px;
  margin: 0 auto;
}
.profile-image {
  width: 100%;
  height: 100%;
  background: var(--bg-light);
  border: 1px solid rgba(255,255,255,0.05);
  /* background-image: url(&#039;assets/daniphoto.jpg&#039;); */
  background-size: cover;
  background-position: center;
}

/* === CONTACT === */
.centered {
  text-align: center;
}
.contact-form {
  max-width: 500px;
  margin: 0 auto 3rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.contact-form input,
.contact-form textarea {
  padding: 1rem 1.5rem;
  background: var(--bg-light);
  border: 1px solid rgba(255,255,255,0.05);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 1rem;
  transition: border-color 0.3s;
}
.contact-form input:focus,
.contact-form textarea:focus {
  outline: none;
  border-color: var(--accent-pink);
}
.social-links {
  display: flex;
  gap: 2rem;
  justify-content: center;
}
.social-links a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  transition: color 0.3s;
}
.social-links a:hover {
  color: var(--text);
}

/* === REVEAL (GSAP target) === */
.reveal {
  opacity: 0;
  transform: translateY(40px);
}

/* === RESPONSIVE === */
@media (max-width: 768px) {
  .layout-split {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .layout-split.alt {
    direction: ltr;
  }
  .col-cards {
    grid-template-columns: 1fr;
  }
  .stats {
    gap: 1.5rem;
  }
  .stat-num {
    font-size: 1.8rem;
  }
  #side-nav {
    right: 1rem;
  }
  .slide {
    padding: 4rem 5vw;
  }
}
