// === LOADER ===
window.addEventListener(&#039;load&#039;, () =&gt; {
  setTimeout(() =&gt; {
    document.getElementById(&#039;loader&#039;).classList.add(&#039;hidden&#039;);
    initAnimations();
  }, 800);
});

// === INIT ===
function initAnimations() {
  gsap.registerPlugin(ScrollTrigger);

  // === SIDE NAV ACTIVE STATE ===
  const sections = document.querySelectorAll(&#039;.slide&#039;);
  sections.forEach((section, i) =&gt; {
    ScrollTrigger.create({
      trigger: section,
      start: &#039;top center&#039;,
      end: &#039;bottom center&#039;,
      onEnter: () =&gt; updateNav(i),
      onEnterBack: () =&gt; updateNav(i)
    });
  });

  function updateNav(activeIndex) {
    document.querySelectorAll(&#039;.nav-dot&#039;).forEach((dot, i) =&gt; {
      dot.classList.toggle(&#039;active&#039;, i === activeIndex);
    });
  }

  // === SECTION REVEALS ===
  document.querySelectorAll(&#039;.slide&#039;).forEach(section =&gt; {
    const reveals = section.querySelectorAll(&#039;.reveal&#039;);
    if (reveals.length) {
      gsap.to(reveals, {
        y: 0,
        opacity: 1,
        duration: 0.8,
        stagger: 0.12,
        ease: &#039;power3.out&#039;,
        scrollTrigger: {
          trigger: section,
          start: &#039;top 75%&#039;,
          toggleActions: &#039;play none none reverse&#039;
        }
      });
    }
  });

  // === HERO LINES ===
  gsap.from(&#039;.hero-title .line&#039;, {
    y: 100,
    opacity: 0,
    duration: 1,
    stagger: 0.2,
    ease: &#039;power3.out&#039;,
    delay: 0.3
  });

  // === SCROLL INDICATOR HIDE ===
  gsap.to(&#039;.scroll-indicator&#039;, {
    opacity: 0,
    scrollTrigger: {
      trigger: &#039;#servicios&#039;,
      start: &#039;top 80%&#039;,
      toggleActions: &#039;play none none none&#039;
    }
  });

  // === PROJECT INTERACTION ===
  const projectItems = document.querySelectorAll(&#039;.project-item&#039;);
  const projectSlides = document.querySelectorAll(&#039;.project-slide&#039;);
  projectItems.forEach(item =&gt; {
    item.addEventListener(&#039;click&#039;, () =&gt; {
      const projectId = item.dataset.project;
      projectItems.forEach(p =&gt; p.classList.remove(&#039;active&#039;));
      item.classList.add(&#039;active&#039;);
      projectSlides.forEach(s =&gt; {
        s.classList.toggle(&#039;active&#039;, s.dataset.project === projectId);
      });
    });
  });

  // === CARD HOVER 3D TILT ===
  document.querySelectorAll(&#039;.card&#039;).forEach(card =&gt; {
    card.addEventListener(&#039;mousemove&#039;, (e) =&gt; {
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const centerX = rect.width / 2;
      const centerY = rect.height / 2;
      const rotateX = (y - centerY) / 20;
      const rotateY = (centerX - x) / 20;
      card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateY(-4px)`;
    });
    card.addEventListener(&#039;mouseleave&#039;, () =&gt; {
      card.style.transform = &#039;&#039;;
    });
  });

  // === SMOOTH SCROLL FOR NAV LINKS ===
  document.querySelectorAll(&#039;.nav-dot&#039;).forEach(dot =&gt; {
    dot.addEventListener(&#039;click&#039;, (e) =&gt; {
      e.preventDefault();
      const target = document.querySelector(dot.getAttribute(&#039;href&#039;));
      gsap.to(window, {duration: 0.8, scrollTo: target, ease: &#039;power3.inOut&#039;});
    });
  });

  // === CONTACT FORM ===
  const form = document.querySelector(&#039;.contact-form&#039;);
  if (form) {
    form.addEventListener(&#039;submit&#039;, (e) =&gt; {
      e.preventDefault();
      const btn = form.querySelector(&#039;button&#039;);
      btn.textContent = &#039;Enviado ✓&#039;;
      btn.style.background = &#039;var(--accent-green)&#039;;
      setTimeout(() =&gt; {
        btn.textContent = &#039;Enviar mensaje&#039;;
        btn.style.background = &#039;&#039;;
        form.reset();
      }, 2000);
    });
  }
}

